//! Approved signed movements. Loan outstanding never reduces available a second time.
use crate::{models::*,money::{self,invalid,text},policy,process::{self,Source},repository::{self,Delta},settings};
use chrono::{DateTime,Utc};
use school_authorization::ActorContext;
use school_errors::AppError;
use school_permissions::registry::codes;
use sqlx::{types::Json,PgPool,Postgres,Transaction};
use uuid::Uuid;
#[derive(Debug,Clone,sqlx::FromRow)]pub(crate) struct AdjustmentRecord{pub id:Uuid,pub owner_id:Uuid,pub revision:i64,pub status:String,pub document:Json<BudgetAdjustmentInput>,pub instance_id:Option<Uuid>,pub created_at:DateTime<Utc>}
pub(crate) async fn record(pool:&PgPool,id:Uuid)->Result<AdjustmentRecord,AppError>{sqlx::query_as("SELECT id,owner_id,revision,status,document,instance_id,created_at FROM budget_adjustments WHERE id=$1").bind(id).fetch_optional(pool).await?.ok_or_else(||AppError::NotFound("ไม่พบรายการปรับงบประมาณ".into()))}
async fn locked(tx:&mut Transaction<'_,Postgres>,id:Uuid)->Result<AdjustmentRecord,AppError>{sqlx::query_as("SELECT id,owner_id,revision,status,document,instance_id,created_at FROM budget_adjustments WHERE id=$1 FOR UPDATE").bind(id).fetch_optional(&mut **tx).await?.ok_or_else(||AppError::NotFound("ไม่พบรายการปรับงบประมาณ".into()))}
fn project_ids(input:&BudgetAdjustmentInput)->Vec<Uuid>{input.from.iter().chain(&input.to).map(|r|r.project_id).collect()}
fn same(a:&BudgetAllocationRef,b:&BudgetAllocationRef)->bool{a.project_id==b.project_id&&a.activity_id==b.activity_id&&a.fund_id==b.fund_id&&a.expense_category_id==b.expense_category_id}
fn validate(input:&BudgetAdjustmentInput)->Result<(),AppError>{money::positive_money(&input.amount_satang)?;text(&input.reason,4000)?;let shape=match input.kind{BudgetAdjustmentKind::Add=>input.from.is_none()&&input.to.is_some()&&input.loan_id.is_none(),BudgetAdjustmentKind::Reduce=>input.from.is_some()&&input.to.is_none()&&input.loan_id.is_none(),BudgetAdjustmentKind::Transfer|BudgetAdjustmentKind::Loan=>input.from.is_some()&&input.to.is_some()&&input.loan_id.is_none(),BudgetAdjustmentKind::Repayment=>input.from.is_some()&&input.to.is_some()&&input.loan_id.is_some()};if !shape{return Err(invalid("ต้นทาง ปลายทาง หรือรายการยืมไม่ตรงประเภทรายการ"));}if let(Some(f),Some(t))=(&input.from,&input.to){if same(f,t)||f.fund_id!=t.fund_id{return Err(invalid("ย้ายหรือยืมงบต้องใช้แหล่งเงินเดียวกันและคนละหมวดงบ"));}}Ok(())}
async fn validate_refs(tx:&mut Transaction<'_,Postgres>,input:&BudgetAdjustmentInput)->Result<(),AppError>{validate(input)?;settings::routing(tx).await?;for r in input.from.iter().chain(&input.to){let p:Option<(Uuid,Option<Uuid>)>=sqlx::query_as("SELECT fiscal_year_id,accepted_snapshot_id FROM budget_projects WHERE id=$1").bind(r.project_id).fetch_optional(&mut **tx).await?;if p.is_none_or(|p|p.0!=input.fiscal_year_id||p.1.is_none()){return Err(invalid("รายการต้องอยู่ในปีงบประมาณเดียวกันและโครงการมีแผนอนุมัติ"));}repository::account(tx,r).await?;}
 if let Some(loan)=input.loan_id{let old:Option<Json<BudgetAdjustmentInput>>=sqlx::query_scalar("SELECT document FROM budget_loans WHERE id=$1 FOR UPDATE").bind(loan).fetch_optional(&mut **tx).await?;let old=old.ok_or_else(||invalid("ไม่พบรายการยืมที่อนุมัติ"))?;if !matches!(old.kind,BudgetAdjustmentKind::Loan)||old.fiscal_year_id!=input.fiscal_year_id||!old.from.as_ref().zip(input.to.as_ref()).is_some_and(|(a,b)|same(a,b))||!old.to.as_ref().zip(input.from.as_ref()).is_some_and(|(a,b)|same(a,b)){return Err(invalid("คืนเงินต้องย้อนต้นทางและปลายทางของรายการยืมเดิม"));}}Ok(())}
pub(crate) async fn require_read(pool:&PgPool,a:&ActorContext,r:&AdjustmentRecord)->Result<(),AppError>{let s=policy::read_scope(pool,a,false).await?;if s.school||(s.own&&r.owner_id==a.user_id){return Ok(());}if s.assigned{let assigned:bool=sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM process_participants WHERE instance_id=$1 AND user_id=$2)").bind(r.instance_id).bind(a.user_id).fetch_one(pool).await?;if assigned{return Ok(());}}for id in project_ids(&r.document){let p=repository::project(pool,id).await?;if !s.units.contains(&p.document.project.organization_unit_id){return Err(repository::denied());}}Ok(())}
async fn project_reads(pool:&PgPool,a:&ActorContext,input:&BudgetAdjustmentInput)->Result<(),AppError>{for id in project_ids(input){let p=repository::project(pool,id).await?;policy::require_read(pool,a,&p).await?;}Ok(())}
async fn detail_tx(tx:&mut Transaction<'_,Postgres>,a:&ActorContext,r:&AdjustmentRecord)->Result<BudgetAdjustmentDetail,AppError>{let i=process::load(tx,r.instance_id).await?;let outstanding:Option<i64>=sqlx::query_scalar("SELECT amount-repaid FROM budget_loans WHERE id=$1").bind(if r.document.kind==BudgetAdjustmentKind::Repayment{r.document.loan_id.unwrap_or(r.id)}else{r.id}).fetch_optional(&mut **tx).await?;let can_edit=a.user_id==r.owner_id&&a.has_permission(codes::BUDGET_ADJUSTMENT_CREATE_SCHOOL)&&repository::parse_status(&r.status)?.editable();let capabilities=policy::capabilities(a,can_edit,policy::can_act(a,i.as_ref(),r.owner_id),true);let p=&r.document;Ok(BudgetAdjustmentDetail{id:r.id,revision:r.revision,owner_id:r.owner_id,status:repository::parse_status(&r.status)?,kind:p.kind,fiscal_year_id:p.fiscal_year_id,from:p.from.clone(),to:p.to.clone(),amount_satang:p.amount_satang.clone(),reason:p.reason.clone(),loan_id:p.loan_id,loan_outstanding_satang:outstanding.unwrap_or(0).to_string(),created_at:r.created_at,capabilities})}
pub async fn detail(pool:&PgPool,a:&ActorContext,id:Uuid)->Result<BudgetAdjustmentDetail,AppError>{
 let scope=policy::read_scope(pool,a,false).await?;let mut tx=pool.begin().await?;sqlx::query("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY").execute(&mut *tx).await?;
 let r:AdjustmentRecord=sqlx::query_as("SELECT id,owner_id,revision,status,document,instance_id,created_at FROM budget_adjustments WHERE id=$1").bind(id).fetch_optional(&mut *tx).await?.ok_or_else(||AppError::NotFound("ไม่พบรายการปรับงบประมาณ".into()))?;
 let projects:Vec<repository::ProjectRecord>=sqlx::query_as("SELECT id,owner_id,revision,status,attempt_id,accepted_version,accepted_snapshot_id,document,instance_id FROM budget_projects WHERE id=ANY($1)").bind(project_ids(&r.document)).fetch_all(&mut *tx).await?;
 require_read_in_transaction(&mut tx,a,&r,&projects,&scope).await?;let d=detail_tx(&mut tx,a,&r).await?;tx.commit().await?;Ok(d)
}

pub async fn create(pool:&PgPool,a:&ActorContext,input:SaveBudgetAdjustmentRequest)->Result<BudgetAdjustmentDetail,AppError>{a.require_permission(codes::BUDGET_ADJUSTMENT_CREATE_SCHOOL)?;let doc=BudgetAdjustmentInput{kind:input.kind,fiscal_year_id:input.fiscal_year_id,from:input.from.clone(),to:input.to.clone(),amount_satang:money::positive_money(&input.amount_satang)?.to_string(),reason:text(&input.reason,4000)?,loan_id:input.loan_id};validate(&doc)?;project_reads(pool,a,&doc).await?;let scope=policy::read_scope(pool,a,false).await?;if !scope.school&&!scope.own{for id in project_ids(&doc){let p=repository::project(pool,id).await?;if !scope.units.contains(&p.document.project.organization_unit_id){return Err(repository::denied());}}}let read_scope=policy::read_scope(pool,a,false).await?;let mut tx=pool.begin().await?;let locked_projects=repository::lock_projects(&mut tx,&project_ids(&doc)).await?;for p in &locked_projects{policy::require_read_in_transaction(&mut tx,a,p,&read_scope).await?;}let id=Uuid::now_v7();if let Some(old)=repository::claim(&mut tx,a.user_id,input.request_id,"adjustment_create",id,&input).await?{tx.commit().await?;return detail(pool,a,old).await;}validate_refs(&mut tx,&doc).await?;sqlx::query("INSERT INTO budget_adjustments(id,owner_id,fiscal_year_id,from_project_id,to_project_id,revision,status,document) VALUES($1,$2,$3,$4,$5,1,'draft',$6)").bind(id).bind(a.user_id).bind(doc.fiscal_year_id).bind(doc.from.as_ref().map(|x|x.project_id)).bind(doc.to.as_ref().map(|x|x.project_id)).bind(Json(doc)).execute(&mut *tx).await?;repository::history(&mut tx,a,BudgetResourceKind::Adjustment,id,1,"created",None).await?;tx.commit().await?;detail(pool,a,id).await}
pub async fn save(pool:&PgPool,a:&ActorContext,id:Uuid,input:UpdateBudgetAdjustmentRequest)->Result<BudgetAdjustmentDetail,AppError>{a.require_permission(codes::BUDGET_ADJUSTMENT_CREATE_SCHOOL)?;let old=record(pool,id).await?;require_read(pool,a,&old).await?;let doc=BudgetAdjustmentInput{kind:input.kind,fiscal_year_id:input.fiscal_year_id,from:input.from.clone(),to:input.to.clone(),amount_satang:money::positive_money(&input.amount_satang)?.to_string(),reason:text(&input.reason,4000)?,loan_id:input.loan_id};validate(&doc)?;let mut ids=project_ids(&old.document);ids.extend(project_ids(&doc));let read_scope=policy::read_scope(pool,a,false).await?;let mut tx=pool.begin().await?;let locked_projects=repository::lock_projects(&mut tx,&ids).await?;let mut r=locked(&mut tx,id).await?;require_read_in_transaction(&mut tx,a,&r,&locked_projects,&read_scope).await?;if r.owner_id!=a.user_id||!repository::parse_status(&r.status)?.editable(){return Err(repository::denied());}if project_ids(&r.document).iter().any(|x|!ids.contains(x)){return Err(repository::stale());}for id in project_ids(&doc){let p=locked_projects.iter().find(|p|p.id==id).ok_or_else(repository::stale)?;policy::require_read_in_transaction(&mut tx,a,p,&read_scope).await?;}if repository::claim(&mut tx,a.user_id,input.request_id,"adjustment_save",id,&(id,&input)).await?.is_some(){tx.commit().await?;return detail(pool,a,id).await;}repository::revision(r.revision,input.expected_revision)?;validate_refs(&mut tx,&doc).await?;r.document=Json(doc);r.revision+=1;sqlx::query("UPDATE budget_adjustments SET revision=$2,fiscal_year_id=$3,from_project_id=$4,to_project_id=$5,document=$6 WHERE id=$1").bind(id).bind(r.revision).bind(r.document.fiscal_year_id).bind(r.document.from.as_ref().map(|x|x.project_id)).bind(r.document.to.as_ref().map(|x|x.project_id)).bind(&r.document).execute(&mut *tx).await?;repository::history(&mut tx,a,BudgetResourceKind::Adjustment,id,r.revision,"saved",None).await?;tx.commit().await?;detail(pool,a,id).await}
pub async fn submit(pool:&PgPool,a:&ActorContext,id:Uuid,input:BudgetMutationRequest)->Result<BudgetAdjustmentDetail,AppError>{a.require_permission(codes::BUDGET_ADJUSTMENT_CREATE_SCHOOL)?;let old=record(pool,id).await?;require_read(pool,a,&old).await?;let ids=project_ids(&old.document);let read_scope=policy::read_scope(pool,a,false).await?;let mut tx=pool.begin().await?;let locked_projects=repository::lock_projects(&mut tx,&ids).await?;let mut r=locked(&mut tx,id).await?;require_read_in_transaction(&mut tx,a,&r,&locked_projects,&read_scope).await?;if project_ids(&r.document).iter().any(|x|!ids.contains(x)){return Err(repository::stale());}if r.owner_id!=a.user_id{return Err(repository::denied());}if repository::claim(&mut tx,a.user_id,input.request_id,"adjustment_submit",id,&(id,&input)).await?.is_some(){tx.commit().await?;return detail(pool,a,id).await;}repository::revision(r.revision,input.expected_revision)?;if !repository::parse_status(&r.status)?.editable(){return Err(repository::stale());}validate_refs(&mut tx,&r.document).await?;let route=settings::routing(&mut tx).await?;let s=Source{resource_type:"budget_adjustment",resource_id:id,owner_id:r.owner_id,actor_id:a.user_id};let i=process::start(&mut tx,a,&s,input.request_id,route.adjustment_template_id,r.document.reason.clone(),format!("/staff/budget/adjustments/{id}")).await?;r.instance_id=Some(i.id);r.status="submitted".into();r.revision+=1;sqlx::query("UPDATE budget_adjustments SET revision=$2,status=$3,instance_id=$4 WHERE id=$1").bind(id).bind(r.revision).bind(&r.status).bind(r.instance_id).execute(&mut *tx).await?;repository::history(&mut tx,a,BudgetResourceKind::Adjustment,id,r.revision,"submitted",None).await?;tx.commit().await?;detail(pool,a,id).await}
async fn apply(tx:&mut Transaction<'_,Postgres>,a:&ActorContext,r:&AdjustmentRecord)->Result<(),AppError>{let doc=&r.document;validate_refs(tx,doc).await?;let amount=money::positive_money(&doc.amount_satang)?;if let Some(from)=&doc.from{repository::post(tx,a.user_id,from,Delta{adjusted:-amount,..Default::default()},"adjustment",r.id).await?;}if let Some(to)=&doc.to{repository::post(tx,a.user_id,to,Delta{adjusted:amount,..Default::default()},"adjustment",r.id).await?;}match doc.kind{BudgetAdjustmentKind::Loan=>{sqlx::query("INSERT INTO budget_loans(id,amount,document) VALUES($1,$2,$3)").bind(r.id).bind(amount).bind(doc).execute(&mut **tx).await?;},BudgetAdjustmentKind::Repayment=>{let loan=doc.loan_id.ok_or_else(||invalid("ไม่พบรายการยืม"))?;let changed=sqlx::query("UPDATE budget_loans SET repaid=repaid+$2 WHERE id=$1 AND repaid+$2<=amount").bind(loan).bind(amount).execute(&mut **tx).await?;if changed.rows_affected()!=1{return Err(invalid("ยอดคืนเกินเงินยืมค้างคืน"));}sqlx::query("INSERT INTO budget_repayments(adjustment_id,loan_id,amount) VALUES($1,$2,$3)").bind(r.id).bind(loan).bind(amount).execute(&mut **tx).await?;},_=>{}}Ok(())}
pub async fn act(pool:&PgPool,a:&ActorContext,id:Uuid,input:BudgetActionRequest)->Result<BudgetAdjustmentDetail,AppError>{let old=record(pool,id).await?;require_read(pool,a,&old).await?;let ids=project_ids(&old.document);let read_scope=policy::read_scope(pool,a,false).await?;let mut tx=pool.begin().await?;let locked_projects=repository::lock_projects(&mut tx,&ids).await?;let mut r=locked(&mut tx,id).await?;require_read_in_transaction(&mut tx,a,&r,&locked_projects,&read_scope).await?;if project_ids(&r.document).iter().any(|x|!ids.contains(x)){return Err(repository::stale());}if repository::claim(&mut tx,a.user_id,input.request_id,"adjustment_action",id,&(id,&input)).await?.is_some(){tx.commit().await?;return detail(pool,a,id).await;}repository::revision(r.revision,input.expected_revision)?;if r.status!="submitted"{return Err(repository::stale());}let s=Source{resource_type:"budget_adjustment",resource_id:id,owner_id:r.owner_id,actor_id:a.user_id};let i=process::act(&mut tx,a,&s,r.instance_id,&input).await?;let status=process::status(&i);if status==BudgetStatus::Approved{apply(&mut tx,a,&r).await?;}r.status=status.as_str().into();r.revision+=1;sqlx::query("UPDATE budget_adjustments SET revision=$2,status=$3 WHERE id=$1").bind(id).bind(r.revision).bind(&r.status).execute(&mut *tx).await?;repository::history(&mut tx,a,BudgetResourceKind::Adjustment,id,r.revision,status.as_str(),input.comment).await?;tx.commit().await?;detail(pool,a,id).await}
pub async fn list(pool:&PgPool,a:&ActorContext,q:BudgetListQuery)->Result<BudgetAdjustmentPage,AppError>{let s=policy::read_scope(pool,a,false).await?;let(limit,offset)=money::paging(&q)?;let filter="($1 OR ($2 AND x.owner_id=$3) OR ((x.from_project_id IS NULL OR f.organization_unit_id=ANY($4)) AND (x.to_project_id IS NULL OR t.organization_unit_id=ANY($4))) OR ($5 AND EXISTS(SELECT 1 FROM process_participants pp WHERE pp.instance_id=x.instance_id AND pp.user_id=$3))) AND ($6::uuid IS NULL OR x.from_project_id=$6 OR x.to_project_id=$6) AND ($7::uuid IS NULL OR x.fiscal_year_id=$7) AND ($8::text IS NULL OR x.status=$8)";let mut tx=pool.begin().await?;sqlx::query("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY").execute(&mut *tx).await?;let total:i64=sqlx::query_scalar(sqlx::AssertSqlSafe(format!("SELECT count(*) FROM budget_adjustments x LEFT JOIN budget_projects f ON f.id=x.from_project_id LEFT JOIN budget_projects t ON t.id=x.to_project_id WHERE {filter}"))).bind(s.school).bind(s.own).bind(a.user_id).bind(&s.units).bind(s.assigned).bind(q.project_id).bind(q.fiscal_year_id).bind(q.status.map(|x|x.as_str())).fetch_one(&mut *tx).await?;let rows:Vec<AdjustmentRecord>=sqlx::query_as(sqlx::AssertSqlSafe(format!("SELECT x.id,x.owner_id,x.revision,x.status,x.document,x.instance_id,x.created_at FROM budget_adjustments x LEFT JOIN budget_projects f ON f.id=x.from_project_id LEFT JOIN budget_projects t ON t.id=x.to_project_id WHERE {filter} ORDER BY x.created_at DESC,x.id DESC LIMIT $9 OFFSET $10"))).bind(s.school).bind(s.own).bind(a.user_id).bind(s.units).bind(s.assigned).bind(q.project_id).bind(q.fiscal_year_id).bind(q.status.map(|x|x.as_str())).bind(limit).bind(offset).fetch_all(&mut *tx).await?;let mut items=vec![];for r in rows{items.push(detail_tx(&mut tx,a,&r).await?);}tx.commit().await?;Ok(BudgetAdjustmentPage{items,total,limit,offset})}
#[cfg(test)]mod tests{use super::*;#[test]fn funding_and_shape_are_explicit(){let r=BudgetAllocationRef{project_id:Uuid::now_v7(),activity_id:Uuid::now_v7(),fund_id:Uuid::now_v7(),expense_category_id:Uuid::now_v7()};let mut input=BudgetAdjustmentInput{kind:BudgetAdjustmentKind::Transfer,fiscal_year_id:Uuid::now_v7(),from:Some(r.clone()),to:Some(r),amount_satang:"100".into(),reason:"test".into(),loan_id:None};assert!(validate(&input).is_err());input.to.as_mut().unwrap().activity_id=Uuid::now_v7();assert!(validate(&input).is_ok());input.to.as_mut().unwrap().fund_id=Uuid::now_v7();assert!(validate(&input).is_err());}}

async fn require_read_in_transaction(tx:&mut Transaction<'_,Postgres>,a:&ActorContext,r:&AdjustmentRecord,projects:&[repository::ProjectRecord],s:&policy::Scope)->Result<(),AppError>{
 if s.school||(s.own&&r.owner_id==a.user_id){return Ok(());}
 if s.assigned&&sqlx::query_scalar::<_,bool>("SELECT EXISTS(SELECT 1 FROM process_participants WHERE instance_id=$1 AND user_id=$2)").bind(r.instance_id).bind(a.user_id).fetch_one(&mut **tx).await?{return Ok(());}
 for id in project_ids(&r.document){let p=projects.iter().find(|p|p.id==id).ok_or_else(repository::stale)?;if !s.units.contains(&p.document.project.organization_unit_id){return Err(repository::denied());}}Ok(())
}
